+import React, { useCallback, useEffect, useMemo, useState } from "react";
+import { Room, RoomMember, MatrixClient, ButtonEvent } from "matrix-js-sdk";
+import { MatrixClientPeg } from "../MatrixClientPeg";
+import { PillType } from "../components/views/elements/Pill";
+import Avatar from "../components/views/elements/Avatar";
+import { _getProfileAvatar } from "../utils/Avatar";
+
+export interface UsePermalinkArgs {
+    room?: Room;
+    type?: PillType;
+    url?: string;
+}
+
+export interface HookResult {
+    avatar: React.ReactElement | null;
+    text: string | null;
+    onClick: ((e: ButtonEvent) => void) | null;
+    resourceId: string | null;
+    type: PillType | "space" | null;
+}
+
+/**
+ * Detect the pill type from a permalink URL using Matrix sigils.
+ * "@" -> user, "!" or "#" -> room/alias.
+ */
+function detectTypeFromUrl(url: string): PillType | null {
+    if (!url) return null;
+    if (url.startsWith("@")) {
+        // @room is a special case handled explicitly via type, not URL parsing
+        if (url === "@room") {
+            return PillType.AtRoomMention;
+        }
+        return PillType.UserMention;
+    }
+    if (url.startsWith("!") || url.startsWith("#")) {
+        return PillType.RoomMention;
+    }
+    return null;
+}
+
+/**
+ * Resolve the display text for a room or alias pill.
+ * Prefer the room's display name; fall back to the room ID/alias.
+ */
+function resolveRoomText(room: Room | null, resourceId: string): string {
+    if (room && room.name) {
+        return room.name;
+    }
+    return resourceId;
+}
+
+/**
+ * Resolve the display text for a user pill.
+ * Prefer the member's display name; fall back to the full Matrix ID.
+ */
+function resolveUserText(member: RoomMember | null, userId: string): string {
+    if (member && member.displayName) {
+        return member.displayName;
+    }
+    return userId;
+}
+
+/**
+ * Determine the avatar element for a pill, or null if none can be resolved.
+ */
+function resolveAvatar(
+    type: PillType | "space" | null,
+    room: Room | null,
+    member: RoomMember | null,
+    resourceId: string,
+    shouldShowPillAvatar: boolean,
+): React.ReactElement | null {
+    if (!shouldShowPillAvatar) return null;
+
+    if (type === PillType.AtRoomMention && room) {
+        return (
+            <Avatar
+                element={room}
+                sizePx={16}
+                resizeMethod="crop"
+                width={16}
+                height={16}
+            />
+        );
+    }
+
+    if (type === PillType.RoomMention || type === "space") {
+        if (room) {
+            return (
+                <Avatar
+                    element={room}
+                    sizePx={16}
+                    resizeMethod="crop"
+                    width={16}
+                    height={16}
+                />
+            );
+        }
+        return null;
+    }
+
+    if (type === PillType.UserMention) {
+        if (member) {
+            const avatarUrl = member.getMainProfile().avatarUrl;
+            if (avatarUrl) {
+                return (
+                    <Avatar
+                        url={avatarUrl}
+                        sizePx={16}
+                        resizeMethod="crop"
+                        width={16}
+                        height={16}
+                    />
+                );
+            }
+        }
+        return null;
+    }
+
+    return null;
+}
+
+/**
+ * React hook that processes a Matrix permalink and returns data ready to render a pill.
+ *
+ * Given { room?, type?, url? }, it resolves the effective type, raw identifier,
+ * human-friendly text, an optional avatar element, and an optional user onClick handler.
+ * When resolution is not possible, it returns null values so that Pill renders nothing.
+ */
+export function usePermalink(args: UsePermalinkArgs): HookResult {
+    const { room, type, url } = args;
+
+    const [member, setMember] = useState<RoomMember | null>(null);
+    const [resolvedRoom, setResolvedRoom] = useState<Room | null>(null);
+
+    // Determine the effective type
+    let effectiveType: PillType | "space" | null = null;
+    let resourceId: string | null = null;
+
+    if (type) {
+        effectiveType = type;
+        resourceId = url || null;
+    } else if (url) {
+        const detected = detectTypeFromUrl(url);
+        if (detected) {
+            effectiveType = detected;
+            resourceId = url;
+        }
+    }
+
+    // For room/alias mentions, try to resolve the room object
+    useEffect(() => {
+        if (effectiveType === PillType.RoomMention && resourceId && room) {
+            // If resourceId is an alias or room ID, try to get the room
+            const client = MatrixClientPeg.get();
+            if (client) {
+                const resolved = client.getRoomById(resourceId) || client.getRoomAlias(resourceId);
+                setResolvedRoom(resolved || null);
+            }
+        } else {
+            setResolvedRoom(null);
+        }
+    }, [effectiveType, resourceId, room]);
+
+    // For user mentions, look up the member
+    useEffect(() => {
+        if (effectiveType === PillType.UserMention && resourceId && room) {
+            const member = room.getMember(resourceId);
+            setMember(member || null);
+        } else {
+            setMember(null);
+        }
+    }, [effectiveType, resourceId, room]);
+
+    // Determine the text to display
+    let text: string | null = null;
+    if (effectiveType === PillType.AtRoomMention) {
+        text = "@room";
+    } else if (effectiveType === PillType.RoomMention) {
+        const targetRoom = resolvedRoom || room;
+        text = resolveRoomText(targetRoom, resourceId || "");
+    } else if (effectiveType === PillType.UserMention) {
+        text = resolveUserText(member, resourceId || "");
+    }
+
+    // Determine the avatar
+    const shouldShowPillAvatar = true;
+    const avatar = resolveAvatar(effectiveType, resolvedRoom || room, member, resourceId || "", shouldShowPillAvatar);
+
+    // Determine the onClick handler for user pills in message context
+    const onClick = useCallback((e: ButtonEvent) => {
+        if (effectiveType === PillType.UserMention && member) {
+            const client = MatrixClientPeg.get();
+            if (client) {
+                client.getRoomMemberProfile(member.userId);
+            }
+        }
+    }, [effectiveType, member]);
+
+    // If we cannot confidently infer a target entity, return nulls
+    if (!effectiveType || !resourceId) {
+        return {
+            avatar: null,
+            text: null,
+            onClick: null,
+            resourceId: null,
+            type: null,
+        };
+    }
+
+    // Check if the resolved room is a Space
+    let finalType: PillType | "space" | null = effectiveType;
+    if (effectiveType === PillType.RoomMention && resolvedRoom) {
+        const isSpace = resolvedRoom.isSpace ? true : (resolvedRoom as any).isSpace;
+        if (isSpace) {
+            finalType = "space";
+        }
+    }
+
+    return {
+        avatar,
+        text,
+        onClick,
+        resourceId,
+        type: finalType,
+    };
